/* Two 1px rules on top of each other under the link. At rest the first is drawn and the second
   is collapsed. On hover the first shrinks away towards the right while the second grows in from
   the left after 0.3s; leaving reverses it. Both use the text colour. */
.aat-architecten-line-link::before,
.aat-architecten-line-link::after {
  content: "";
  position: absolute;
  inset-inline: 0;
  bottom: 0;
  height: 1px;
  background-color: currentColor;
  transition: scale 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}
.aat-architecten-line-link::before {
  scale: 1 1;
  transform-origin: left center;
  transition-delay: 0.3s;
}
.aat-architecten-line-link::after {
  scale: 0 1;
  transform-origin: right center;
}
.aat-architecten-line-link:is(:hover, :focus-visible)::before {
  scale: 0 1;
  transform-origin: right center;
  transition-delay: 0s;
}
.aat-architecten-line-link:is(:hover, :focus-visible)::after {
  scale: 1 1;
  transform-origin: left center;
  transition-delay: 0.3s;
}

@media (prefers-reduced-motion: reduce) {
  .aat-architecten-line-link::before,
  .aat-architecten-line-link::after {
    transition: none;
  }
}

import type { ReactNode } from "react";
import { ArrowRight } from "lucide-react";
import { cn } from "@foundry/foundry-utils";
import "./aat-architecten-line-link.css";

export interface AatArchitectenLineLinkProps {
  /** the label */
  children: ReactNode;
  /** where it goes */
  href: string;
  className?: string;
}

/** Label left, arrow right, on a 1px rule 230px wide. 16px text on phones, 20px from 1024px. */
export function AatArchitectenLineLink({ children, href, className }: AatArchitectenLineLinkProps) {
  return (
    <a
      href={href}
      className={cn(
        "aat-architecten-line-link relative inline-flex w-[14.375rem] max-w-full items-center justify-between gap-4 pb-3 font-sans text-base leading-none text-foreground outline-none lg:text-xl",
        className,
      )}
    >
      <span>{children}</span>
      <ArrowRight aria-hidden className="size-4 shrink-0" strokeWidth={1.5} />
    </a>
  );
}
